-- ============================================================================
-- B5 FOLLOW-ON W4a (typed-case panel modes): geomech.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1
-- route (b), and docs/graded-field-audit/w4a/geomech.json. Owner approved D1
-- to D7 as recommended, 2026-09-21 (D2: the panel guard forbids a DEFAULT
-- state that lands on a graded answer; typing the case is the work).
--
-- INTERMEDIATE
--   Collapse, fracture initiation, breakout and the window at 2000 m run the
--   Associate capstone's parameter set and a Horsrud UCS; the At one depth view
--   took only depth, inclination and azimuth. W4a adds a box for every parameter
--   and one for the UCS (blank is published). The brief now names the view and
--   states the two parameters of the set it did not repeat. Prompt only.
--   PROMPT was: Free check: field 4 plus field 6 must equal field 5 exactly,
--   because all three are the same pressures divided by the same denominator.
--   PROMPT now: Free check: field 4 plus field 6 must equal field 5 exactly,
--   because all three are the same pressures divided by the same denominator.
--   The stability explorer's At one depth view takes every parameter of the set
--   as a typed input (including the Associate capstone's Young's modulus of
--   18000000000 Pa and strains of 0.0002 and 0.0005) and the UCS.
--
-- ADVANCED
--   The two whole-trajectory walks run the capstone parameter set, and the
--   window view took only Poisson ratio, friction angle and SHmax azimuth, and
--   printed no collapse at the tightest point. W4a adds the other five parameter
--   boxes (all blank by default) and tiles for collapse and fracture initiation
--   at the tightest point. The brief now names the view. Prompt only.
--   PROMPT was: You should be able to say which well is which before running
--   anything.
--   PROMPT now: You should be able to say which well is which before running
--   anything. The mud window explorer's Along the well view takes every
--   parameter as a typed input and prints the collapse and fracture initiation
--   gradients at the tightest point.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after.
--
-- ATTEMPTS. Prompt copy only: no graded key or tolerance moves, so no attempt
-- can be graded differently and there is no attempts guard.
--
-- GUARDS. Each row must hold EITHER its live prompt (by md5) and fields (exact
-- jsonb) as the W1-state scratch replay has them (it is rewritten), OR its W4a
-- form (left alone). Anything else raises and the whole file rolls back. A
-- file that will write first checks that W1 is applied and refuses without it.
-- Generated by docs/graded-field-audit/w4a_capstones.py. SAFE TO RE-RUN: a
-- second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
begin
  -- geomech / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'geomech' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w4a geomech refused: geomech/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '6606c53c6cc896a0d7834866be5961db' and fields = '[{"key": "collapse_Pa", "tol": 50, "unit": "Pa", "label": "Collapse pressure", "expected": 14628899.208552536}, {"key": "frac_init_Pa", "tol": 50, "unit": "Pa", "label": "Fracture initiation", "expected": 45176234.71145374}, {"key": "breakout_theta_deg", "tol": 0.5, "unit": "deg", "label": "Breakout angle", "expected": 84}, {"key": "collapse_emw_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Collapse EMW", "expected": 745.8662850490502}, {"key": "frac_init_emw_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Fracture initiation EMW", "expected": 2303.346948828282}, {"key": "window_width_emw_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Window width", "expected": 1557.480663779232}]'::jsonb then 'old'
              when md5(prompt) = '47d710c30a5860a3c888cc3f8dffcdcb' and fields = '[{"key": "collapse_Pa", "tol": 50, "unit": "Pa", "label": "Collapse pressure", "expected": 14628899.208552536}, {"key": "frac_init_Pa", "tol": 50, "unit": "Pa", "label": "Fracture initiation", "expected": 45176234.71145374}, {"key": "breakout_theta_deg", "tol": 0.5, "unit": "deg", "label": "Breakout angle", "expected": 84}, {"key": "collapse_emw_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Collapse EMW", "expected": 745.8662850490502}, {"key": "frac_init_emw_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Fracture initiation EMW", "expected": 2303.346948828282}, {"key": "window_width_emw_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Window width", "expected": 1557.480663779232}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'geomech' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w4a geomech refused: geomech/intermediate matches neither its live form (prompt md5 6606c53c6cc896a0d7834866be5961db) nor its W4a form (prompt md5 47d710c30a5860a3c888cc3f8dffcdcb), with the fields this file was generated against';
  end if;

  -- geomech / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'geomech' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w4a geomech refused: geomech/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '2d6651268f360a7c4fc136a6242d72fb' and fields = '[{"key": "slant_tightest_width_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant window width", "expected": 1317.993874508228}, {"key": "slant_collapse_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant collapse gradient", "expected": 248.10414286699674}, {"key": "slant_frac_init_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant fracture gradient", "expected": 2496.6949229689703}, {"key": "horizontal_tightest_width_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal window width", "expected": 1343.3180035349267}, {"key": "horizontal_collapse_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal collapse gradient", "expected": 1411.1968938126954}, {"key": "horizontal_frac_init_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal fracture gradient", "expected": 2754.514897347622}]'::jsonb then 'old'
              when md5(prompt) = '66ef72d813e5d7a837719068abc36fc3' and fields = '[{"key": "slant_tightest_width_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant window width", "expected": 1317.993874508228}, {"key": "slant_collapse_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant collapse gradient", "expected": 248.10414286699674}, {"key": "slant_frac_init_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant fracture gradient", "expected": 2496.6949229689703}, {"key": "horizontal_tightest_width_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal window width", "expected": 1343.3180035349267}, {"key": "horizontal_collapse_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal collapse gradient", "expected": 1411.1968938126954}, {"key": "horizontal_frac_init_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal fracture gradient", "expected": 2754.514897347622}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'geomech' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w4a geomech refused: geomech/advanced matches neither its live form (prompt md5 2d6651268f360a7c4fc136a6242d72fb) nor its W4a form (prompt md5 66ef72d813e5d7a837719068abc36fc3), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W4a form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w4a geomech: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024a/b) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active and md5(prompt) = '27fc6852586864af77f23cdbbf2deacc')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'petrophysics' and c.tier = 'advanced' and c.active and f->>'key' = 'sw_waterleg_mean'
                   and (f->>'tol')::float8 = 0.005) then
    raise exception 'w4a geomech refused: W1 (20261024a/b) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six numbers at 2000 m of true vertical depth, on the SAME parameter set as the Associate capstone: Poisson ratio 0.24, friction angle 26 degrees, Biot coefficient 0.9, SHmax azimuth 105 degrees, tensile strength 2500000 Pa. The two horizontal stresses are the Associate capstone''s fields 3 and 4, and the strength is its field 5, the HORSRUD value for the 233 microsecond per metre core plug reading, NOT the profile''s own published UCS at that depth. The hole is at an INCLINATION of 55 degrees on an AZIMUTH of 130 degrees; the lessons run 0, 30, 60 and 90 degrees on azimuths of 0, 60 and 150, so neither of these is one of them. Report: (1) the COLLAPSE pressure in pascals; (2) the FRACTURE INITIATION pressure in pascals; (3) the BREAKOUT ANGLE in degrees from the HIGH SIDE of the hole, which is a borehole-frame angle and not a compass bearing; (4) the collapse EQUIVALENT MUD WEIGHT; (5) the fracture initiation equivalent mud weight; and (6) the WINDOW WIDTH in equivalent mud weight. Free check: field 4 plus field 6 must equal field 5 exactly, because all three are the same pressures divided by the same denominator. The stability explorer''s At one depth view takes every parameter of the set as a typed input (including the Associate capstone''s Young''s modulus of 18000000000 Pa and strains of 0.0002 and 0.0005) and the UCS.'
     where app_slug = 'geomech' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w4a geomech refused: geomech/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '47d710c30a5860a3c888cc3f8dffcdcb' and fields = '[{"key": "collapse_Pa", "tol": 50, "unit": "Pa", "label": "Collapse pressure", "expected": 14628899.208552536}, {"key": "frac_init_Pa", "tol": 50, "unit": "Pa", "label": "Fracture initiation", "expected": 45176234.71145374}, {"key": "breakout_theta_deg", "tol": 0.5, "unit": "deg", "label": "Breakout angle", "expected": 84}, {"key": "collapse_emw_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Collapse EMW", "expected": 745.8662850490502}, {"key": "frac_init_emw_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Fracture initiation EMW", "expected": 2303.346948828282}, {"key": "window_width_emw_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Window width", "expected": 1557.480663779232}]'::jsonb) from public.academy_capstones where app_slug = 'geomech' and tier = 'intermediate' and active) is not true then
    raise exception 'w4a geomech refused: geomech/intermediate does not read back as its W4a form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Six numbers from two whole-trajectory walks, on the SAME capstone parameter set as the two tiers before it: Poisson ratio 0.24, friction angle 26 degrees, Young''s modulus 18000000000 Pa, strains 0.0002 and 0.0005, Biot coefficient 0.9, SHmax azimuth 105 degrees, tensile strength 2500000 Pa. On the SLANT well, at the tightest point of its walk, report (1) the WINDOW WIDTH, (2) the COLLAPSE gradient there and (3) the FRACTURE INITIATION gradient there. Then on the HORIZONTAL well, at the tightest point of ITS walk, report (4) the window width, (5) the collapse gradient and (6) the fracture initiation gradient. All six are EQUIVALENT MUD WEIGHTS in kg/m3. Three traps. The tightest point MOVES at these parameters, so the depth the lessons print is the wrong row. Fields 2 and 5 ask for the COLLAPSE gradient specifically, not the lower bound, so on the well where the pore pressure binds the collapse gradient sits well below the floor and is still the answer. And the window width is measured from the LOWER BOUND, so field 5 plus field 4 equals field 6 exactly on the collapse-bound well while field 2 plus field 1 does NOT equal field 3 on the other one. You should be able to say which well is which before running anything. The mud window explorer''s Along the well view takes every parameter as a typed input and prints the collapse and fracture initiation gradients at the tightest point.'
     where app_slug = 'geomech' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w4a geomech refused: geomech/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '66ef72d813e5d7a837719068abc36fc3' and fields = '[{"key": "slant_tightest_width_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant window width", "expected": 1317.993874508228}, {"key": "slant_collapse_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant collapse gradient", "expected": 248.10414286699674}, {"key": "slant_frac_init_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant fracture gradient", "expected": 2496.6949229689703}, {"key": "horizontal_tightest_width_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal window width", "expected": 1343.3180035349267}, {"key": "horizontal_collapse_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal collapse gradient", "expected": 1411.1968938126954}, {"key": "horizontal_frac_init_emw_at_tightest_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal fracture gradient", "expected": 2754.514897347622}]'::jsonb) from public.academy_capstones where app_slug = 'geomech' and tier = 'advanced' and active) is not true then
    raise exception 'w4a geomech refused: geomech/advanced does not read back as its W4a form';
  end if;

  raise notice 'w4a geomech: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
